868	static int32_t bsp_otm8009a_write(uint16_t Addr, uint16_t Reg, uint8_t *pData, uint16_t Length)
869	{
870	  (void)Addr;
871	  uint8_t buf[64];
872	  buf[0] = (uint8_t)Reg;
873	  int32_t ret;
874	  g_otm8009a_cmd_count++;
875	
876	  if (Length > 0 && pData != NULL) {
877	    if (Length > 60) Length = 60;
878	    for (uint16_t i = 0; i < Length; i++) {
879	      buf[i + 1] = pData[i];
880	    }
881	    ret = DSI_IO_WriteCmd(Length, buf);
882	  } else {
883	    buf[1] = (pData != NULL) ? pData[0] : 0;
884	    ret = DSI_IO_WriteCmd(0, buf);
885	  }
886	
887	  if (ret != 0 && g_otm8009a_first_err_ret == 0) {
888	    g_otm8009a_first_err_ret = ret;
889	    g_otm8009a_first_err_idx = g_otm8009a_cmd_count;
890	    g_otm8009a_first_err_reg = Reg;
891	  }
892	  return ret;
893	}
